import Foundation
import Testing
@testable import StrimTemplate

/// Fixture generated by the HF tokenizer's apply_chat_template via bench/oracle/template_dump.py (script removed 2026-10-27, in history bundle); the JSON is frozen data.
private let fixtureURL = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
    .appendingPathComponent("bench/fixtures/template_parity.json")

private func loadCases() throws -> [OrderedJSON] {
    let text = try String(contentsOf: fixtureURL, encoding: .utf8)
    guard case let .array(cases) = try OrderedJSON.parse(text) else { throw TemplateError("fixture is not an array") }
    return cases
}

private struct RenderInput {
    var messages: [Message]
    var tools: [ToolSpec]
    var gen: Bool
    var enableThinking: Bool?
    var policy: ReasoningPolicy
    var toolChoice: String?
    var effort: String?
    var preserve: Bool?

    init(_ c: OrderedJSON) throws {
        guard case let .array(ms)? = c["messages"] else { throw TemplateError("no messages") }
        messages = try ms.map { try Message(json: $0) }
        if case let .array(ts)? = c["tools"] { tools = ts.map { ToolSpec(json: $0) } } else { tools = [] }
        if case let .bool(g)? = c["add_generation_prompt"] { gen = g } else { gen = true }
        if case let .bool(b)? = c["enable_thinking"] { enableThinking = b }
        policy = ReasoningPolicy(rawValue: c["policy"]?.stringValue ?? "") ?? .templateDefault
        toolChoice = c["tool_choice"]?.stringValue
        effort = c["reasoning_effort"]?.stringValue
        if case let .bool(b)? = c["preserve_thinking"] { preserve = b }
    }

    func segments() throws -> [Segment] {
        try ChatTemplate.renderSegments(
            messages: messages, tools: tools, addGenerationPrompt: gen, enableThinking: enableThinking,
            reasoningPolicy: policy, toolChoice: toolChoice, reasoningEffort: effort, preserveThinking: preserve)
    }
}

private func firstDiff(_ a: String, _ b: String) -> String {
    let x = Array(a.utf8), y = Array(b.utf8)
    var i = 0
    while i < min(x.count, y.count), x[i] == y[i] { i += 1 }
    func ctx(_ v: [UInt8]) -> String { String(decoding: v[max(0, i - 40)..<min(v.count, i + 80)], as: UTF8.self) }
    return "at byte \(i) (len \(x.count) vs \(y.count))\n  actual:   \(ctx(x).debugDescription)\n  expected: \(ctx(y).debugDescription)"
}

@Test func templateParityAgainstHFOracle() throws {
    let cases = try loadCases()
    #expect(cases.count >= 150)
    var failures = [String]()
    var passed = 0, errorCases = 0
    for c in cases {
        let id = c["id"]?.stringValue ?? "?"
        let expectError: Bool
        if case .bool(true)? = c["error"] { expectError = true } else { expectError = false }
        do {
            let input = try RenderInput(c)
            let segs = try input.segments()
            let actual = segs.map(\.text).joined()
            let direct = try ChatTemplate.render(
                messages: input.messages, tools: input.tools, addGenerationPrompt: input.gen, enableThinking: input.enableThinking,
                reasoningPolicy: input.policy, toolChoice: input.toolChoice, reasoningEffort: input.effort, preserveThinking: input.preserve)
            guard let expected = c["expected"]?.stringValue, !expectError else {
                failures.append("\(id): expected an error, got a render")
                continue
            }
            if !Array(actual.utf8).elementsEqual(Array(expected.utf8)) {
                failures.append("\(id): \(firstDiff(actual, expected))")
            } else if direct != actual {
                failures.append("\(id): render != joined segments")
            } else {
                passed += 1
            }
        } catch {
            if expectError { errorCases += 1; passed += 1 } else { failures.append("\(id): unexpected error \(error)") }
        }
    }
    print("template parity: \(passed)/\(cases.count) passed (\(errorCases) expected-error cases)")
    #expect(failures.isEmpty, Comment(rawValue: "\(failures.count) failures:\n" + failures.prefix(10).joined(separator: "\n")))
}

/// A caller keeping a token ledger renders only the new turn: the suffix segments of a longer conversation
/// must equal the full render of the longer conversation minus the prefix that was already rendered.
@Test func segmentsSplitAtTurnBoundaries() throws {
    let cases = try loadCases()
    var checked = 0
    for c in cases {
        guard c["expected"] != nil, let input = try? RenderInput(c), let segs = try? input.segments() else { continue }
        // segment ranges must tile the message array in order
        var next = 0
        for s in segs where s.role != "generation_prompt" && !s.messages.isEmpty {
            if s.role == "system" && s.messages.lowerBound == 0 { next = 1; continue }
            #expect(s.messages.lowerBound >= next, "\(c["id"]?.stringValue ?? "")")
            next = s.messages.upperBound
        }
        checked += 1
    }
    #expect(checked >= 150)
}

@Test func suffixRenderMatchesFullRenderForAppendedTurn() throws {
    let tools = [ToolSpec(name: "read_file", description: "Read", parameters: .ordered([("type", .string("object")), ("properties", .ordered([]))]))]
    let history: [Message] = [
        .system("sys"), .user("q1"),
        .assistant("", toolCalls: [ToolCall(name: "read_file", arguments: [("path", .string("a"))])]),
        .tool("res"),
    ]
    let full = history + [.assistant("done", reasoning: "r"), .user("q2")]
    let prefix = try ChatTemplate.renderSegments(messages: history, tools: tools, addGenerationPrompt: false)
    let all = try ChatTemplate.renderSegments(messages: full, tools: tools, addGenerationPrompt: true)
    #expect(Array(all.prefix(prefix.count)) == prefix)
    let tail = all.dropFirst(prefix.count)
    #expect(tail.map { $0.role } == ["assistant", "user", "generation_prompt"])
    #expect(tail.last?.text == "<|im_start|>assistant\n<think>\n\n</think>\n\n")  // disableWhenTools default
}

@Test func defaultPolicyIsDisableWhenTools() throws {
    let tool = ToolSpec(name: "t", description: "d", parameters: .ordered([]))
    let withTools = try ChatTemplate.render(messages: [.user("x")], tools: [tool])
    #expect(withTools.hasSuffix("<|im_start|>assistant\n<think>\n\n</think>\n\n"))
    #expect(!withTools.contains("Reasoning effort"))
    let none = try ChatTemplate.render(messages: [.user("x")], tools: [tool], toolChoice: "none")
    #expect(none.hasSuffix("<|im_start|>assistant\n<think>\n"))
    #expect(!none.contains("# Tools"))
    let plain = try ChatTemplate.render(messages: [.user("x")])
    #expect(plain.hasSuffix("<think>\n") && plain.contains("Reasoning effort is set to xhigh"))
    #expect(ReasoningPolicy.off.resolve(enableThinking: nil, hasTools: false) == false)
    #expect(ReasoningPolicy.on.resolve(enableThinking: false, hasTools: true) == true)
}
